test('Stop Daemon uses an outline danger button with an SVG stop icon', () => {
  const html = fs.readFileSync(path.join(repoRoot, 'webview.html'), 'utf8');
  const css = fs.readFileSync(path.join(repoRoot, 'static/style.css'), 'utf8');
  const stopButton = html.match(/<button[^>]*id="gls-stop-daemon-btn"[\s\S]*?<\/button>/);
  assert.ok(stopButton, 'Stop Daemon button exists');
  const classAttr = stopButton[0].match(/class="([^"]*)"/);
  assert.ok(classAttr, 'Stop Daemon has a class attribute');
  const classes = classAttr[1].split(/\s+/);
  assert.ok(classes.includes('btn-danger-outline'), 'Stop Daemon uses outline danger style');
  assert.equal(classes.includes('btn-danger'), false, 'Stop Daemon no longer uses solid danger style');
  assert.doesNotMatch(stopButton[0], /■/);
  assert.match(stopButton[0], /<svg\b[\s\S]*<rect\b/, 'Stop Daemon renders a stop SVG');
  assert.match(css, /\.btn-danger-outline\s*\{[^}]*background:\s*transparent[^}]*border:/s);
});

test('relay_connection delta patches state in place without a panel/grid rebuild', () => {
  const { context } = createRelayStatusHarness();
  runInContext(context, `
    state.relay_connection = {
      status: 'connected', enabled: true, relay_host: 'relay.runtorque.com',
      retry_count: 0, last_error: '', since: '2026-05-23T10:00:00Z',
    };
    renderMainCalls = 0;
    renderActivePanelCalls = 0;
    lastInvalidations = null;
    _expectedSeq = 1;
  `);
  const beforeRef = jsonValue(context, 'state.relay_connection.status');
  assert.equal(beforeRef, 'connected');

  context._handleDelta({
    seq: 1,
    ops: [
      {
        op: 'relay_connection',
        status: 'error',
        enabled: true,
        relay_host: 'relay.runtorque.com',
        retry_count: 7,
        last_error: 'certificate verify failed',
        since: '2026-05-23T11:00:00Z',
      },
    ],
  });

  // State patched in place.
  assert.equal(jsonValue(context, 'state.relay_connection.status'), 'error');
  assert.equal(jsonValue(context, 'state.relay_connection.retry_count'), 7);
  assert.equal(jsonValue(context, 'state.relay_connection.last_error'), 'certificate verify failed');

  // The op marks NO panel surface — surface-invalidation discipline. Either
  // renderInvalidatedSurfaces was never called (no surface flagged) or every
  // flag is false.
  const inval = jsonValue(context, 'lastInvalidations');
  if (inval) {
    for (const key of Object.keys(inval)) {
      assert.equal(inval[key], false, `surface ${key} must not be marked`);
    }
  }
  // No full-panel / active-panel rebuild triggered.
  assert.equal(jsonValue(context, 'renderMainCalls'), 0);
  assert.equal(jsonValue(context, 'renderActivePanelCalls'), 0);

  // The indicator itself refreshed to the red error dot.
  assert.equal(
    jsonValue(context, `_relayStatusEls.dot.classList.contains('relay-status-dot--red')`),
    true,
  );
});

test('relay_connection modal "Relay" row renders from state and hides when absent', () => {
  const { context } = createRelayStatusHarness();
  // Present field → section visible, fields populated.
  runInContext(context, `
    state.relay_connection = {
      status: 'disconnected', enabled: true, relay_host: 'relay.runtorque.com',
      retry_count: 4, last_error: 'connection reset', since: '2026-05-23T12:00:00Z',
    };
    _relayStatusRenderModalRow();
  `);
  assert.equal(jsonValue(context, `document.getElementById('gls-relay-section').hidden`), false);
  assert.equal(jsonValue(context, `document.getElementById('gls-relay-status-text').textContent`), 'disconnected');
  assert.equal(jsonValue(context, `document.getElementById('gls-relay-host').textContent`), 'relay.runtorque.com');
  assert.equal(jsonValue(context, `document.getElementById('gls-relay-retry-count').textContent`), '4');
  assert.equal(jsonValue(context, `document.getElementById('gls-relay-since').textContent`), '2026-05-23T12:00:00Z');
  assert.equal(jsonValue(context, `document.getElementById('gls-relay-last-error').textContent`), 'connection reset');
  assert.equal(
    jsonValue(context, `document.getElementById('gls-relay-status-dot').classList.contains('relay-status-dot--amber')`),
    true,
  );

  // The modal dot reflects status color — regression guard for the
  // always-grey cascade defect. error → red (and the prior amber is cleared).
  runInContext(context, `
    state.relay_connection = {
      status: 'error', enabled: true, relay_host: 'relay.runtorque.com',
      retry_count: 9, last_error: 'certificate verify failed', since: '2026-05-23T12:05:00Z',
    };
    _relayStatusRenderModalRow();
  `);
  assert.equal(
    jsonValue(context, `document.getElementById('gls-relay-status-dot').classList.contains('relay-status-dot--red')`),
    true,
    'error → red dot class',
  );
  assert.equal(
    jsonValue(context, `document.getElementById('gls-relay-status-dot').classList.contains('relay-status-dot--amber')`),
    false,
    'stale amber class cleared on status change',
  );
  // connected → green.
  runInContext(context, `
    state.relay_connection = {
      status: 'connected', enabled: true, relay_host: 'relay.runtorque.com',
      retry_count: 0, since: '2026-05-23T12:10:00Z',
    };
    _relayStatusRenderModalRow();
  `);
  assert.equal(
    jsonValue(context, `document.getElementById('gls-relay-status-dot').classList.contains('relay-status-dot--green')`),
    true,
    'connected → green dot class',
  );

  // Absent field → section hidden.
  runInContext(context, `
    state.relay_connection = null;
    _relayStatusRenderModalRow();
  `);
  assert.equal(jsonValue(context, `document.getElementById('gls-relay-section').hidden`), true);
});

/* -- Relay config (TORQUE:603 #1) ----------------------------------------- */

// A resolved relay_config payload spanning every source, including
// the inline-PEM private_key_path case (source ee_connector.json, value "").
const RELAY_CONFIG_SAMPLE = {
  config: {
    enabled: true,
    relay_url: 'wss://relay.runtorque.com',
    daemon_id: 'daemon-123',
    credential_id: 'cred-abc',
  },
  sources: {
    enabled: { value: true, source: 'settings' },
    relay_url: { value: 'wss://relay.runtorque.com', source: 'settings' },
    daemon_id: { value: 'daemon-123', source: 'env' },
    credential_id: { value: 'cred-abc', source: 'ee_connector.json' },
    private_key_path: { value: '', source: 'ee_connector.json' },
  },
};

function _relayConfigView(context, payload) {
  context.__relayConfigPayload = (payload === undefined) ? null : payload;
  return jsonValue(context, '_relayConfigComputeView(__relayConfigPayload)');
}

function _relayConfigFieldView(view, key) {
  return view.fields.find((f) => f.key === key);
}

test('relay_config view maps each source to settings-layer values without provenance labels', () => {
  const { context } = createRelayStatusHarness();
  const view = _relayConfigView(context, RELAY_CONFIG_SAMPLE);
  assert.equal(view.visible, true);

  // settings-sourced bool: checkbox reflects the effective value.
  const enabled = _relayConfigFieldView(view, 'enabled');
  assert.equal(enabled.type, 'bool');
  assert.equal(enabled.checked, true);
  assert.equal(Object.prototype.hasOwnProperty.call(enabled, 'sourceLabel'), false);
  assert.equal(Object.prototype.hasOwnProperty.call(enabled, 'sourceClass'), false);

  // settings-sourced text: value flows into the editable input (no placeholder).
  const url = _relayConfigFieldView(view, 'relay_url');
  assert.equal(url.textValue, 'wss://relay.runtorque.com');
  assert.equal(url.placeholder, '');
  assert.equal(Object.prototype.hasOwnProperty.call(url, 'sourceLabel'), false);

  // env-sourced text: NOT a settings override → empty input, effective value as
  // placeholder.
  const daemon = _relayConfigFieldView(view, 'daemon_id');
  assert.equal(daemon.textValue, '');
  assert.equal(daemon.placeholder, 'daemon-123');

  // ee_connector.json-sourced text: empty input, effective value as placeholder,
  // with no badge metadata exposed.
  const cred = _relayConfigFieldView(view, 'credential_id');
  assert.equal(cred.textValue, '');
  assert.equal(cred.placeholder, 'cred-abc');
  assert.equal(Object.prototype.hasOwnProperty.call(cred, 'sourceClass'), false);
});

test('relay_config private_key_path is BY PATH only and never leaks inline PEM', () => {
  const { context } = createRelayStatusHarness();
  // Inline-PEM case: source ee_connector.json, value "" → no value anywhere.
  const view = _relayConfigView(context, RELAY_CONFIG_SAMPLE);
  const key = _relayConfigFieldView(view, 'private_key_path');
  assert.equal(key.textValue, '');
  assert.equal(key.placeholder, '');
  assert.equal(Object.prototype.hasOwnProperty.call(key, 'sourceLabel'), false);
  assert.equal(Object.prototype.hasOwnProperty.call(key, 'sourceClass'), false);

  // A settings-layer PATH is shown verbatim (it's a path, not a PEM).
  const withPath = _relayConfigView(context, {
    config: { private_key_path: '/home/op/relay.pem' },
    sources: { private_key_path: { value: '/home/op/relay.pem', source: 'settings' } },
  });
  const keyPath = _relayConfigFieldView(withPath, 'private_key_path');
  assert.equal(keyPath.textValue, '/home/op/relay.pem');
  assert.equal(Object.prototype.hasOwnProperty.call(keyPath, 'sourceLabel'), false);
});

