test('embedded terminal direct-message resize rail has a dedicated hit-zone outside header and compose controls', () => {
  const terminalSource = fs.readFileSync(path.join(repoRoot, 'static/js/terminal.js'), 'utf8');
  const css = fs.readFileSync(path.join(repoRoot, 'static/style.css'), 'utf8');
  const resizerIndex = terminalSource.indexOf('data-terminal-direct-messages-resizer');
  const sectionIndex = terminalSource.indexOf('<section class="terminal-direct-messages"');
  const headerIndex = terminalSource.indexOf('terminal-direct-messages-header');
  assert.ok(resizerIndex >= 0, 'direct-message resize divider markup exists');
  assert.ok(sectionIndex > resizerIndex, 'resize divider is before the message panel section');
  assert.ok(headerIndex > sectionIndex, 'header controls remain inside the section below the divider');

  const resizerRule = css.match(/\.terminal-direct-messages-resizer\s*\{[^}]+\}/);
  assert.ok(resizerRule, 'direct-message resize divider CSS exists');
  assert.match(resizerRule[0], /height:\s*12px;/);
  assert.match(resizerRule[0], /cursor:\s*ns-resize;/);
  assert.doesNotMatch(resizerRule[0], /position:\s*absolute|inset:|top:|bottom:/);
  assert.match(css, /\.terminal-direct-messages-slot\[data-resized="true"\] \.terminal-direct-messages-list\s*\{[\s\S]*max-height:\s*none;/);
});

test('embedded terminal compose renders only for standalone runtime and preserves drafts across rerenders', () => {
  const { context, document, sandbox } = createEmbeddedTerminalHarness({
    loadRenderHelpers: true,
  });
  const dom = attachTerminalWorkspaceDom(document);
  document.body.classList.add('runtime-embedded');
  sandbox.state.runtime = { embedded_terminal: true };
  sandbox.state.groups = { alpha: ['agent-1'] };
  sandbox.state.group_settings = { alpha: {} };
  sandbox.state.children = { 'agent-1': [] };
  sandbox.state.agents = {
    'agent-1': {
      id: 'agent-1',
      name: 'Builder',
      group: 'alpha',
      cell_type: 'agent',
      session_id: 'sess-1',
      status: 'running',
      current_path: '/repo',
    },
  };

  runInContext(context, `
    selectedAgentId = 'agent-1';
    selectedTerminalId = 'agent-1';
    _embeddedTerminalSessionKey = 'agent-1:sess-1';
    renderTerminalWorkspace();
  `);

  const composeHtml = dom.compose.innerHTML;
  assert.match(composeHtml, /class="terminal-compose"/);
  assert.match(composeHtml, /Send a message to Builder/);
  assert.match(composeHtml, /contenteditable="true"/);
  assert.match(composeHtml, /role="textbox"/);
  assert.doesNotMatch(composeHtml, /terminal-compose-attachments/);
  assert.match(composeHtml, /terminal-compose-history-toggle/);
  assert.match(composeHtml, /aria-label="Message history"/);
  assert.match(composeHtml, /title="Message history \(use ↑\/↓ to recall\)"/);
  assert.match(composeHtml, /onclick="return terminalComposeHistoryToggle\(event, 'agent-1'\)"/);
  assert.match(composeHtml, /<span class="terminal-compose-history-icon" aria-hidden="true">↺<\/span>/);
  assert.doesNotMatch(composeHtml, />History<\/button>/);
  const sendIndex = composeHtml.indexOf('<button id="terminal-compose-submit-agent-1"');
  const historyIndex = composeHtml.indexOf('<div class="terminal-compose-history-wrap">');
  assert.ok(sendIndex >= 0, 'compose send button is rendered');
  assert.ok(historyIndex > sendIndex, 'history icon button follows send in DOM/tab order');

  const input = document.register('terminal-compose-input-agent-1');
  input.classList.add('terminal-compose-input');
  input.dataset.cellId = 'agent-1';
  input.value = 'Draft survives a digest update';
  input.selectionStart = 6;
  input.selectionEnd = 14;
  const button = document.register('terminal-compose-submit-agent-1');
  button.classList.add('terminal-compose-submit');
  dom.compose.appendChild(input);
  dom.compose.appendChild(button);
  dom.compose.setQuerySelector('.terminal-compose-input', input);
  dom.compose.setQuerySelector('.terminal-compose-submit', button);
  dom.workspace.setQuerySelector('.terminal-compose-input', input);
  document.activeElement = input;

  runInContext(context, `
    terminalComposeInput(document.getElementById('terminal-compose-input-agent-1'));
    state.agents['agent-1'].activity_detail = 'Digest arrived';
    renderTerminalWorkspace();
  `);

  assert.equal(input.focused, true);
  assert.equal(input.value, 'Draft survives a digest update');
  assert.equal(input.selectionStart, 6);
  assert.equal(input.selectionEnd, 14);
  assert.equal(button.disabled, false);
  assert.equal(
    jsonValue(context, `_terminalComposeDrafts['agent-1']`),
    'Draft survives a digest update',
  );

  runInContext(context, `
    state.runtime = { embedded_terminal: false };
    document.getElementById('terminal-workspace').innerHTML = '<form class="terminal-compose">stale</form>';
    renderTerminalWorkspace();
  `);

  assert.equal(dom.workspace.innerHTML, '');
  assert.doesNotMatch(dom.workspace.innerHTML, /terminal-compose/);
});


test('embedded terminal rich direct-message composer preserves block-created newline on send', () => {
  const { context, document, sandbox } = createEmbeddedTerminalHarness();
  sandbox.state.groups = { alpha: ['agent-1'] };
  sandbox.state.group_settings = { alpha: {} };
  sandbox.state.agents = {
    'agent-1': {
      id: 'agent-1',
      name: 'Builder',
      group: 'alpha',
      cell_type: 'agent',
      kind: 'worker',
      session_id: 'sess-1',
      status: 'running',
    },
  };

  function textNode(value) {
    return { nodeType: 3, nodeValue: value };
  }
  function elementNode(name, children) {
    return {
      nodeType: 1,
      nodeName: name,
      childNodes: children || [],
      getAttribute() { return null; },
    };
  }

  const form = new FakeElement('terminal-compose-form-agent-1');
  form.classList.add('terminal-compose');
  form.dataset.cellId = 'agent-1';
  const input = document.register('terminal-compose-input-agent-1');
  input.classList.add('terminal-compose-input');
  input.dataset.cellId = 'agent-1';
  input.setAttribute('contenteditable', 'true');
  input.value = 'line oneline two';
  input.childNodes = [
    textNode('line one'),
    elementNode('DIV', [textNode('line two')]),
  ];
  input._innerHTML = 'line one<div>line two</div>';
  const button = document.register('terminal-compose-submit-agent-1');
  button.classList.add('terminal-compose-submit');
  form.appendChild(input);
  form.appendChild(button);
  form.setQuerySelector('.terminal-compose-input', input);
  form.setQuerySelector('.terminal-compose-submit', button);
  document.activeElement = input;

  assert.equal(
    runInContext(context, `_terminalComposeInputText(document.getElementById('terminal-compose-input-agent-1'))`),
    'line one\nline two',
    'contenteditable text followed by a block line serializes with a newline',
  );

  const submitEvt = {
    currentTarget: form,
    preventDefaultCalled: false,
    stopPropagationCalled: false,
    preventDefault() { this.preventDefaultCalled = true; },
    stopPropagation() { this.stopPropagationCalled = true; },
  };
  context.__submitEvt = submitEvt;
  runInContext(context, `terminalComposeSubmit(__submitEvt, 'agent-1');`);

  assert.equal(submitEvt.preventDefaultCalled, true);
  assert.equal(submitEvt.stopPropagationCalled, true);
  assert.equal(sandbox.sendCalls.length, 1);
  assert.equal(sandbox.sendCalls[0].cmd, 'user_agent_message');
  assert.equal(sandbox.sendCalls[0].message, 'line one\nline two');
  assert.doesNotMatch(sandbox.sendCalls[0].message, /line oneline two/);
  assert.equal(input.value, '');
  assert.equal(button.disabled, true);
});

test('embedded terminal rich direct-message composer pastes normalized plain text only', () => {
  const { context, document } = createEmbeddedTerminalHarness();
  const form = new FakeElement('terminal-compose-form-agent-1');
  form.classList.add('terminal-compose');
  form.dataset.cellId = 'agent-1';
  const input = document.register('terminal-compose-input-agent-1');
  input.classList.add('terminal-compose-input');
  input.dataset.cellId = 'agent-1';
  input.setAttribute('contenteditable', 'true');
  input.value = 'before after';
  input.selectionStart = 'before '.length;
  input.selectionEnd = input.value.length;
  const button = document.register('terminal-compose-submit-agent-1');
  button.classList.add('terminal-compose-submit');
  form.appendChild(input);
  form.appendChild(button);
  form.setQuerySelector('.terminal-compose-input', input);
  form.setQuerySelector('.terminal-compose-submit', button);
  document.activeElement = input;

  const pasteEvent = {
    currentTarget: input,
    clipboardData: {
      getData(type) {
        if (type === 'text/plain') return 'Bold\r\nRed\u00a0Text';
        if (type === 'text/html') {
          return '<span style="font-size:48px;color:red"><b>Bold</b></span>';
        }
        return '';
      },
    },
    preventDefaultCalled: false,
    stopPropagationCalled: false,
    preventDefault() { this.preventDefaultCalled = true; },
    stopPropagation() { this.stopPropagationCalled = true; },
  };
  context.__richPasteEvent = pasteEvent;

  runInContext(context, `terminalComposePaste(__richPasteEvent, 'agent-1');`);

  assert.equal(pasteEvent.preventDefaultCalled, true);
  assert.equal(pasteEvent.stopPropagationCalled, true);
  assert.equal(input.value, 'before Bold\nRed Text');
  assert.equal(input.innerHTML, 'before Bold<br>Red Text');
  assert.doesNotMatch(input.innerHTML, /span|style=|font-size|<b>/i);
  assert.equal(input.selectionStart, input.value.length);
  assert.equal(input.selectionEnd, input.value.length);
  assert.equal(button.disabled, false);
  assert.equal(input.focused, true);
  assert.equal(
    jsonValue(context, `_terminalComposeDrafts['agent-1']`),
    'before Bold\nRed Text',
  );
});

