test('terminal compose preserves image chip payload through history recall restore', async () => {
  async function runRecallRestoreFlow(restoreKey) {
    const uploads = [];
    class FakeFormData {
      constructor() {
        this.entries = [];
      }

      append(name, value) {
        this.entries.push([name, value]);
      }
    }

    const fullPath = '/home/testuser/.torque/attachments/agent-1-history.png';
    const { context, document, sandbox } = createEmbeddedTerminalHarness({
      FormData: FakeFormData,
      fetch(url, options) {
        uploads.push({ url, entries: options.body.entries });
        return Promise.resolve({
          json() {
            return Promise.resolve({
              ok: true,
              data: [{ path: fullPath }],
            });
          },
        });
      },
    });
    sandbox.state.agent_message_history = {
      'agent-1': [
        { id: 7, agent_id: 'agent-1', message: 'previous history entry', sent_at: 7 },
      ],
    };

    const form = new FakeElement('compose-form');
    form.classList.add('terminal-compose');
    const input = document.register('terminal-compose-input-agent-1');
    input.classList.add('terminal-compose-input');
    input.dataset.cellId = 'agent-1';
    input.selectionStart = 0;
    input.selectionEnd = 0;
    const error = new FakeElement('compose-error');
    error.classList.add('terminal-compose-error');
    const chips = new FakeElement('compose-attachments');
    chips.classList.add('terminal-compose-attachments');
    const button = document.register('terminal-compose-submit-agent-1');
    button.classList.add('terminal-compose-submit');
    form.appendChild(input);
    form.appendChild(chips);
    form.appendChild(error);
    form.appendChild(button);
    form.setQuerySelector('.terminal-compose-input', input);
    form.setQuerySelector('.terminal-compose-attachments', chips);
    form.setQuerySelector('.terminal-compose-error', error);
    form.setQuerySelector('.terminal-compose-submit', button);

    const image = { type: 'image/png', name: 'history.png', size: 1200 };
    const dropEvent = {
      currentTarget: input,
      dataTransfer: { types: ['Files'], files: [image] },
      preventDefaultCalled: false,
      stopPropagationCalled: false,
      preventDefault() { this.preventDefaultCalled = true; },
      stopPropagation() { this.stopPropagationCalled = true; },
    };

    await context.terminalComposeDrop(dropEvent, 'agent-1');
    assert.equal(dropEvent.preventDefaultCalled, true);
    assert.equal(dropEvent.stopPropagationCalled, true);
    assert.equal(uploads.length, 1);
    assert.equal(input.value, '');
    assert.match(chips.innerHTML, /history\.png/);
    assert.deepEqual(jsonValue(context, `_terminalComposeAttachments['agent-1'].entries.map(function(e) { return { token: e.token, path: e.path, filename: e.filename, position: e.position }; })`), [
      { token: '[ Image #1 ]', path: fullPath, filename: 'history.png', position: 0 },
    ]);

    function keyEvent(key) {
      return {
        key,
        target: input,
        shiftKey: false,
        ctrlKey: false,
        metaKey: false,
        altKey: false,
        preventDefaultCalled: false,
        stopPropagationCalled: false,
        preventDefault() { this.preventDefaultCalled = true; },
        stopPropagation() { this.stopPropagationCalled = true; },
      };
    }

    const up = keyEvent('ArrowUp');
    context.__historyUp = up;
    runInContext(context, `terminalComposeKeydown(__historyUp, 'agent-1');`);
    assert.equal(up.preventDefaultCalled, true);
    assert.equal(up.stopPropagationCalled, true);
    assert.equal(input.value, 'previous history entry');
    assert.deepEqual(jsonValue(context, `_terminalComposeAttachments['agent-1'].entries.map(function(e) { return { token: e.token, path: e.path, position: e.position }; })`), [
      { token: '[ Image #1 ]', path: fullPath, position: 0 },
    ]);

    const restore = keyEvent(restoreKey);
    context.__historyRestore = restore;
    runInContext(context, `terminalComposeKeydown(__historyRestore, 'agent-1');`);
    assert.equal(restore.preventDefaultCalled, true);
    assert.equal(restore.stopPropagationCalled, true);
    assert.equal(input.value, '');
    assert.deepEqual(jsonValue(context, `_terminalComposeAttachments['agent-1'].entries.map(function(e) { return { token: e.token, path: e.path, position: e.position }; })`), [
      { token: '[ Image #1 ]', path: fullPath, position: 0 },
    ]);

    context.__submitHistoryRestore = {
      currentTarget: form,
      preventDefault() {},
      stopPropagation() {},
    };
    runInContext(context, `terminalComposeSubmit(__submitHistoryRestore, 'agent-1');`);
    assert.equal(sandbox.sendCalls.length, 1);
    assert.equal(sandbox.sendCalls[0].cmd, 'send_user_message');
    assert.equal(sandbox.sendCalls[0].cell_id, 'agent-1');
    assert.equal(sandbox.sendCalls[0].text, fullPath);
    assert.equal(jsonValue(context, `_terminalComposeAttachments['agent-1'] || null`), null);
  }

  await runRecallRestoreFlow('ArrowDown');
  await runRecallRestoreFlow('Escape');
});

test('terminal compose slash command autocomplete filters and fills without sending', () => {
  const { context, document, sandbox } = createEmbeddedTerminalHarness();
  sandbox.state.agents = {
    'agent-1': {
      id: 'agent-1',
      name: 'Builder',
      group: 'Torque',
      cell_type: 'agent',
      kind: 'worker',
    },
  };

  const form = new FakeElement('compose-form');
  form.classList.add('terminal-compose');
  const input = document.register('terminal-compose-input-agent-1');
  input.classList.add('terminal-compose-input');
  input.dataset.cellId = 'agent-1';
  input.dataset.agentId = 'agent-1';
  const taskDropdown = document.register('terminal-compose-task-dropdown-agent-1');
  taskDropdown.classList.add('deps-dropdown');
  taskDropdown.classList.add('terminal-compose-task-dropdown');
  taskDropdown.style.display = 'none';
  const slashDropdown = document.register('terminal-compose-slash-dropdown-agent-1');
  slashDropdown.classList.add('deps-dropdown');
  slashDropdown.classList.add('terminal-compose-slash-dropdown');
  slashDropdown.style.display = 'none';
  const button = document.register('terminal-compose-submit-agent-1');
  button.classList.add('terminal-compose-submit');
  form.appendChild(input);
  form.appendChild(taskDropdown);
  form.appendChild(slashDropdown);
  form.appendChild(button);
  form.setQuerySelector('.terminal-compose-submit', button);

  input.value = '/';
  input.selectionStart = input.value.length;
  input.selectionEnd = input.value.length;
  context.terminalComposeInput(input);

  assert.equal(slashDropdown.style.display, '');
  assert.equal(taskDropdown.style.display, 'none');
  assert.match(slashDropdown.innerHTML, /\/compact/);
  assert.match(slashDropdown.innerHTML, /\/restart/);
  assert.match(slashDropdown.innerHTML, /\/loop every <interval> <message>/);
  assert.match(slashDropdown.innerHTML, /\/loop cancel/);
  assert.match(slashDropdown.innerHTML, /recurring user message/i);
  assert.equal(sandbox.sendCalls.length, 0);

  input.value = '/loop c';
  input.selectionStart = input.value.length;
  input.selectionEnd = input.value.length;
  context.terminalComposeInput(input);
  assert.equal(slashDropdown.style.display, '');
  assert.match(slashDropdown.innerHTML, /\/loop cancel/);
  assert.doesNotMatch(slashDropdown.innerHTML, /\/loop every <interval> <message>/);
  assert.doesNotMatch(slashDropdown.innerHTML, /\/compact/);
  assert.doesNotMatch(slashDropdown.innerHTML, /\/restart/);

  function keyEvent(key) {
    return {
      key,
      target: input,
      shiftKey: false,
      ctrlKey: false,
      metaKey: false,
      altKey: false,
      preventDefaultCalled: false,
      stopPropagationCalled: false,
      preventDefault() { this.preventDefaultCalled = true; },
      stopPropagation() { this.stopPropagationCalled = true; },
    };
  }

  const enterCancel = keyEvent('Enter');
  context.__enterCancel = enterCancel;
  runInContext(context, `terminalComposeKeydown(__enterCancel, 'agent-1');`);
  assert.equal(enterCancel.preventDefaultCalled, true);
  assert.equal(enterCancel.stopPropagationCalled, true);
  assert.equal(input.value, '/loop cancel');
  assert.equal(input.selectionStart, input.value.length);
  assert.equal(input.selectionEnd, input.value.length);
  assert.equal(input.focused, true);
  assert.equal(slashDropdown.style.display, 'none');
  assert.equal(jsonValue(context, `_terminalComposeDrafts['agent-1']`), '/loop cancel');
  assert.equal(sandbox.sendCalls.length, 0);

  input.focused = false;
  input.value = '/lo';
  input.selectionStart = input.value.length;
  input.selectionEnd = input.value.length;
  context.terminalComposeInput(input);
  const optionEvery = new FakeElement('slash-opt-every');
  const optionCancel = new FakeElement('slash-opt-cancel');
  optionEvery.classList.add('deps-option');
  optionCancel.classList.add('deps-option');
  slashDropdown.setQuerySelectorAll('.deps-option', [optionEvery, optionCancel]);

  const arrowDown = keyEvent('ArrowDown');
  context.__slashArrowDown = arrowDown;
  runInContext(context, `terminalComposeKeydown(__slashArrowDown, 'agent-1');`);
  assert.equal(arrowDown.preventDefaultCalled, true);
  assert.equal(optionEvery.classList.contains('active'), true);
  assert.equal(optionCancel.classList.contains('active'), false);

  const enterEvery = keyEvent('Enter');
  context.__enterEvery = enterEvery;
  runInContext(context, `terminalComposeKeydown(__enterEvery, 'agent-1');`);
  assert.equal(enterEvery.preventDefaultCalled, true);
  assert.equal(enterEvery.stopPropagationCalled, true);
  assert.equal(input.value, '/loop every 10m ');
  assert.equal(input.selectionStart, input.value.length);
  assert.equal(input.selectionEnd, input.value.length);
  assert.equal(sandbox.sendCalls.length, 0);

  input.value = '/res';
  input.selectionStart = input.value.length;
  input.selectionEnd = input.value.length;
  context.terminalComposeInput(input);
  assert.equal(slashDropdown.style.display, '');
  assert.match(slashDropdown.innerHTML, /\/restart/);
  assert.doesNotMatch(slashDropdown.innerHTML, /\/compact/);
  const enterRestart = keyEvent('Enter');
  context.__enterRestart = enterRestart;
  runInContext(context, `terminalComposeKeydown(__enterRestart, 'agent-1');`);
  assert.equal(enterRestart.preventDefaultCalled, true);
  assert.equal(input.value, '/restart');
  assert.equal(sandbox.sendCalls.length, 0);

  context.__restartSubmit = {
    currentTarget: form,
    preventDefault() {},
    stopPropagation() {},
  };
  runInContext(context, `terminalComposeSubmit(__restartSubmit, 'agent-1');`);
  assert.equal(sandbox.sendCalls.length, 1);
  assert.equal(sandbox.sendCalls[0].cmd, 'user_agent_message');
  assert.equal(sandbox.sendCalls[0].agent_id, 'agent-1');
  assert.equal(sandbox.sendCalls[0].message, '/restart');
  assert.match(sandbox.sendCalls[0].idempotency_key, /^terminal-direct:agent-1:/);

  input.value = '/not-a-command';
  input.selectionStart = input.value.length;
  input.selectionEnd = input.value.length;
  context.terminalComposeInput(input);
  assert.equal(slashDropdown.style.display, 'none');
  context.__invalidSlashSubmit = {
    currentTarget: form,
    preventDefault() {},
    stopPropagation() {},
  };
  runInContext(context, `terminalComposeSubmit(__invalidSlashSubmit, 'agent-1');`);
  assert.equal(sandbox.sendCalls.length, 2);
  assert.equal(sandbox.sendCalls[1].cmd, 'user_agent_message');
  assert.equal(sandbox.sendCalls[1].agent_id, 'agent-1');
  assert.equal(sandbox.sendCalls[1].message, '/not-a-command');
});

