test('incoming direct_message_upsert refreshes the real terminal direct-message panel', () => {
  const { sandbox, document } = createSandbox();
  const workspace = document.register('terminal-workspace');
  workspace.classList.add('active');
  document.body.classList.add('runtime-embedded');
  const context = vm.createContext(sandbox);
  loadScript(context, 'static/js/ws.js');
  loadScript(context, 'static/js/render.js');
  loadScript(context, 'static/js/grid/group-tabs.js');
  loadScript(context, 'static/js/grid/agent-card.js');
  loadScript(context, 'static/js/grid/terminal-row.js');
  loadScript(context, 'static/js/grid/sections.js');
  loadScript(context, 'static/js/agent-detail.js');
  loadScript(context, 'static/js/agent-focus.js');
  loadScript(context, 'static/js/grid/main.js');
  loadScript(context, 'static/js/terminal.js');
  const dom = attachTerminalWorkspaceDom(document);

  runInContext(context, `
    var __terminalRefreshCalls = 0;
    render = function(opts) {
      if (!opts || !opts.skipTerminalRefresh) {
        __terminalRefreshCalls += 1;
        renderTerminalWorkspace();
      }
    };
    updateEventsAttentionBadge = function() {};
    _expectedSeq = 1;
    state.runtime = { embedded_terminal: true };
    state.groups = { alpha: ['worker-1'] };
    state.group_settings = { alpha: {} };
    state.children = { 'worker-1': [] };
    state.agents = {
      'worker-1': {
        id: 'worker-1',
        name: 'Worker',
        group: 'alpha',
        cell_type: 'agent',
        kind: 'worker',
        session_id: '',
        status: 'stopped'
      }
    };
    selectedTerminalId = 'worker-1';
    selectedAgentId = 'worker-1';
    renderTerminalWorkspace();
  `);
  assert.doesNotMatch(dom.directMessages.innerHTML, /delta hello/);

  context._handleDelta({
    seq: 1,
    ops: [{
      op: 'direct_message_upsert',
      message_id: 'delta-dm-1',
      agent_id: 'worker-1',
      group: 'alpha',
      message: {
        message_id: 'delta-dm-1',
        thread_id: 'user-agent:user:worker-1',
        message: 'delta hello',
        message_type: 'message',
        created_at: '2026-05-22T12:45:00Z',
        sender_id: 'worker-1',
        sender_kind: 'worker',
        sender_name: 'Worker',
        recipient_id: 'user',
        recipient_kind: 'user',
      },
    }],
  });

  assert.equal(runInContext(context, `__terminalRefreshCalls`), 1,
    'viewed direct message delta must refresh the real terminal workspace');
  assert.match(dom.directMessages.innerHTML, /delta hello/);
  assert.match(dom.directMessages.innerHTML, /terminal-direct-message--agent-to-user/);
});

test('mcp_call_append for non-focused agent does NOT invalidate engineer panel (TORQUE:236 v4)', () => {
  // P0 TORQUE:236 final fix: cross-agent MCP traffic used to clobber the
  // focused engineer panel via _renderSurface('engineer') -> renderAgentPanel(),
  // destroying the textarea node + scroll anchor on every worker MCP call,
  // even though nothing the panel displayed had changed. The fix gates
  // engineer-surface invalidation on `cell_id === focused agent id`.
  const { context, sandbox, rafCallbacks, flushRaf } = createStandaloneDeltaBatchHarness(['engineer']);
  // User has focused agent-1; another worker (agent-2) fires an MCP call.
  runInContext(context, `selectedAgentId = 'agent-1';`);
  context._handleDelta({
    seq: 1,
    ops: [{
      op: 'mcp_call_append',
      group: 'alpha',
      call: {
        cell_id: 'agent-2',
        tool_name: 'mcp__torque__torque_progress',
        hook_event_name: 'PostToolUse',
        cursor: 1,
      },
    }],
  });
  flushRaf();
  // Engineer panel must NOT have re-rendered for cross-agent MCP traffic.
  assert.equal(sandbox.renderCalls.engineer, 0,
    'mcp_call_append for non-focused agent should not refresh engineer panel');
});

