  context.state.agents = {
    'worker-1': {
      id: 'worker-1',
      name: 'Worker One',
      kind: 'worker',
      group: 'alpha',
      cell_type: 'agent',
    },
  };
  context.focusedItemId = 'worker-1';
  context.state.board_tasks = {};
