test('dismissed architect decision panel hides mutators and blocks stale handlers', () => {
  const { context, document } = createEngineerHarness();
  const panel = document.register('panel-agent');

  context.state.agents = {
    'arch-1': {
      id: 'arch-1',
      name: 'Architect One',
      kind: 'architect',
      group: 'alpha',
      cell_type: 'agent',
      dismissed_at: 123,
    },
    'eng-1': {
      id: 'eng-1',
      name: 'Engineer One',
      kind: 'engineer',
      group: 'alpha',
      cell_type: 'agent',
      hired_by_architect_id: 'arch-1',
    },
  };
  context.state.board_tasks = {
    'TORQUE:1': { id: 'TORQUE:1', task: 'Implement decision', group: 'alpha' },
  };
  context.state.decisions = {
    proposed: {
      id: 'proposed',
      architect_id: 'arch-1',
      title: 'Proposed decision',
      rationale: 'Readable while the architect is dismissed.',
      status: 'proposed',
      created_at: 10,
      updated_at: 10,
    },
  };
  context.focusedItemId = 'arch-1';

  runInContext(context, `
    _agentPanelLastSelectedTabByKind.architect = 'decisions';
    _engineerDecisionUiState('proposed', state.decisions.proposed).expanded = true;
    renderAgentPanel();
  `);

  assert.match(panel.innerHTML, /Readable while the architect is dismissed/);
  assert.doesNotMatch(panel.innerHTML, />Edit<\/button>/);
  assert.doesNotMatch(panel.innerHTML, /aria-label="Acknowledge decision"/);
  assert.doesNotMatch(panel.innerHTML, />Archive<\/button>/);
  assert.doesNotMatch(panel.innerHTML, />Link task<\/button>/);
  assert.doesNotMatch(panel.innerHTML, /Link task…/);
  assert.doesNotMatch(panel.innerHTML, /Link engineer…/);

  runInContext(context, `
    var toastCalls = [];
    _showToast = function(message, level) { toastCalls.push({ message: message, level: level }); };
    engineerStartDecisionEdit('proposed');
    var ui = _engineerDecisionUiState('proposed', state.decisions.proposed);
    ui.editing = true;
    ui.link_task_id = 'TORQUE:1';
    ui.link_engineer_id = 'eng-1';
    engineerSaveDecisionEdit('arch-1', 'proposed');
    engineerAcknowledgeDecision('arch-1', 'proposed');
    engineerArchiveDecision('arch-1', 'proposed');
    engineerLinkDecisionTask('arch-1', 'proposed');
    engineerLinkDecisionEngineer('arch-1', 'proposed');
  `);

  assert.deepEqual(JSON.parse(JSON.stringify(context.sendCalls)), []);
  assert.equal(jsonValue(context, `_engineerArchitectDecisionUi.proposed.editing`), false);
  assert.deepEqual(jsonValue(context, `toastCalls.map(function(item) { return item.level + ':' + item.message; })`), [
    'warning:Rehire architect to modify decisions',
    'warning:Rehire architect to modify decisions',
    'warning:Rehire architect to modify decisions',
    'warning:Rehire architect to modify decisions',
    'warning:Rehire architect to modify decisions',
    'warning:Rehire architect to modify decisions',
  ]);
});

test('architect decision and message caches invalidate on relevant websocket deltas', () => {
  const { context, document } = createEngineerWsHarness();
  const panel = document.getElementById('panel-agent');
  panel.querySelector = function() { return null; };
  runInContext(context, `
    state.groups = { alpha: ['arch-1'] };
    state.agents = {
      'arch-1': {
        id: 'arch-1',
        name: 'Architect One',
        kind: 'architect',
        group: 'alpha',
        cell_type: 'agent',
        mcp_messages: [
          { id: 'msg-old', action: 'progress', message: 'Old architect message', timestamp: 10 }
        ],
      },
    };
    state.decisions = {
      'decision-1': {
        id: 'decision-1',
        architect_id: 'arch-1',
        title: 'Old cached decision',
        rationale: 'old',
        status: 'proposed',
        updated_at: 10,
      },
    };
    focusedItemId = 'arch-1';
    _agentPanelLastSelectedTabByKind.architect = 'decisions';
    _expectedSeq = 1;
    renderAgentPanel();
  `);
  assert.match(panel.innerHTML, /Old cached decision/);

  context._handleDelta({
    seq: 1,
    ops: [{
      op: 'decision_upsert',
      id: 'decision-1',
      architect_id: 'arch-1',
      title: 'Fresh decision from delta',
      rationale: 'new',
      status: 'accepted',
      updated_at: 11,
    }],
  });

  assert.match(panel.innerHTML, /Fresh decision from delta/);
  assert.doesNotMatch(panel.innerHTML, /Old cached decision/);

  runInContext(context, `
    _agentPanelLastSelectedTabByKind.architect = 'messages';
    renderAgentPanel();
    _expectedSeq = 2;
  `);
  assert.match(panel.innerHTML, /Old architect message/);

  context._handleDelta({
    seq: 2,
    ops: [{
      op: 'agent_upsert',
      id: 'arch-1',
      mcp_messages: [
        { id: 'msg-new', action: 'architect_reply', message: 'Fresh architect message', timestamp: 20 }
      ],
    }],
  });

  assert.match(panel.innerHTML, /Fresh architect message/);
  assert.doesNotMatch(panel.innerHTML, /Old architect message/);

  runInContext(context, `_expectedSeq = 3;`);
  context._handleDelta({
    seq: 3,
    ops: [{
      op: 'peer_message_upsert',
      agent_id: 'arch-1',
      group: 'alpha',
      message: {
        id: 'peer-msg-1',
        action: 'architect_peer_message',
        message: 'Dedicated peer delta message',
        timestamp: 30,
        peer_id: 'arch-2',
        peer_kind: 'architect',
        direction: 'received',
        ack_required: true,
      },
    }],
  });

  assert.match(panel.innerHTML, /Dedicated peer delta message/);
  assert.match(panel.innerHTML, /Ack required/);
});

test('ws task deltas avoid rerendering worker worklog for unrelated assigned tasks', () => {
  const { context, sandbox, flushRaf } = createStandaloneDeltaBatchHarness(['engineer']);
  runInContext(context, `
    _activePanelApp = 'engineer';
    focusedItemId = 'worker-1';
    state.agents = {
      'worker-1': { id: 'worker-1', kind: 'worker', group: 'alpha', cell_type: 'agent' },
      'worker-2': { id: 'worker-2', kind: 'worker', group: 'alpha', cell_type: 'agent' },
    };
    state.board_tasks = {
      'other-task': {
        id: 'other-task',
        task: 'Unrelated work',
        group: 'alpha',
        agent_id: 'worker-2',
        lane: 'In Progress'
      }
    };
    _currentGroup = function() { return 'alpha'; };
    _resolveFocusedAgent = function() { return state.agents[focusedItemId] || null; };
    _agentPanelKind = function(agent) { return (agent && agent.kind) || 'worker'; };
    _agentPanelActiveTab = function() { return 'worklog'; };
  `);

  context._handleDelta({
    seq: 1,
    ops: [{
      op: 'task_upsert',
      id: 'other-task',
      task: 'Unrelated work updated',
      group: 'alpha',
      agent_id: 'worker-2',
      lane: 'In Progress',
    }],
  });
  flushRaf();

  assert.equal(sandbox.renderCalls.engineer, 0);
});

