test('chat panel renders message markdown with escaped raw HTML and safe links', () => {
  const { context, document } = createChatHarness();
  setChatThreads(context, {
    'thread-md': makeChatThread('thread-md', {
      ts: 300,
      title: 'Markdown Thread',
      message: [
        '## Plan',
        'Use **bold**, *italic*, and `code`.',
        '- [Safe](mailto:ops@example.com)',
        '- Bare http://chat.example/docs, and mailto:support@example.com.',
        '- [Nope](data:text/html,<svg onload=alert(1)>)',
        '```',
        '<script>alert("x")</script>',
        '```',
        '<img src=x onerror=alert(1)>',
      ].join('\n'),
    }),
  });

  context.renderChatPanel();

  const html = document.getElementById('panel-chat')._chatShell._chatParts.messages.innerHTML;
  assert.match(html, /data-chat-message-id="thread-md-msg"/);
  assert.match(html, /class="chat-message-body torque-markdown"/);
  assert.match(html, /<h2>Plan<\/h2>/);
  assert.match(html, /<strong>bold<\/strong>/);
  assert.match(html, /<em>italic<\/em>/);
  assert.match(html, /<code class="torque-md-inline-code">code<\/code>/);
  assert.match(html, /href="mailto:ops@example\.com" target="_blank" rel="noopener noreferrer">Safe<\/a>/);
  assert.match(html, /href="http:\/\/chat\.example\/docs" target="_blank" rel="noopener noreferrer">http:\/\/chat\.example\/docs<\/a>,/);
  assert.match(html, /href="mailto:support@example\.com" target="_blank" rel="noopener noreferrer">mailto:support@example\.com<\/a>\./);
  assert.match(html, /<span class="torque-md-link-disabled" title="Unsafe link removed">Nope<\/span>/);
  assert.match(html, /<pre class="torque-md-code-block"><code>&lt;script&gt;alert\(&quot;x&quot;\)&lt;\/script&gt;<\/code><\/pre>/);
  assert.match(html, /&lt;img src=x onerror=alert\(1\)&gt;/);
  assert.doesNotMatch(html, /<script\b/i);
  assert.doesNotMatch(html, /<img\b/i);
  assert.doesNotMatch(html, /href="(?:javascript|data):/i);
});

test('markdown code blocks reserve horizontal scrollbar space for message bodies', () => {
  const css = fs.readFileSync(path.join(repoRoot, 'static/style.css'), 'utf8');
  const blockRule = css.match(/\.torque-markdown \.torque-md-code-block\s*\{[^}]*\}/s);
  assert.ok(blockRule, 'markdown code block CSS rule exists');
  assert.match(blockRule[0], /overflow-x:\s*auto;/);
  assert.match(
    blockRule[0],
    /padding:\s*0\.6em 0\.7em calc\(0\.6em \+ var\(--torque-md-code-scrollbar-space\)\);/,
    'bottom padding reserves room for overlay horizontal scrollbars',
  );
  assert.match(blockRule[0], /scrollbar-gutter:\s*stable;/);
  assert.match(blockRule[0], /scrollbar-width:\s*thin;/);
  assert.match(blockRule[0], /scrollbar-color:\s*color-mix\(in srgb, var\(--text-dim\) 58%, transparent\) transparent;/);

  const webkitRule = css.match(/\.torque-markdown \.torque-md-code-block::-webkit-scrollbar\s*\{[^}]*\}/s);
  assert.ok(webkitRule, 'WebKit scrollbar rule exists for browser and desktop webviews');
  assert.match(webkitRule[0], /height:\s*var\(--torque-md-code-scrollbar-space\);/);

  const thumbRule = css.match(/\.torque-markdown \.torque-md-code-block::-webkit-scrollbar-thumb\s*\{[^}]*\}/s);
  assert.ok(thumbRule, 'WebKit scrollbar thumb rule exists');
  assert.match(thumbRule[0], /background:\s*color-mix\(in srgb, var\(--text-dim\) 58%, transparent\);/);
  assert.match(thumbRule[0], /border:\s*2px solid transparent;/);
});

test('chat message context menu copies raw source text rather than rendered markdown', () => {
  const { context, document } = createChatHarness();
  const menu = document.register('ctx-menu');
  let copied = '';
  context.navigator.clipboard.writeText = function(value) {
    copied = String(value);
    return { then(resolve) { if (resolve) resolve(); } };
  };
  const raw = '**raw bold** <em>literal</em> [Docs](https://example.com)';
  setChatThreads(context, {
    'thread-copy': makeChatThread('thread-copy', {
      ts: 300,
      title: 'Copy Thread',
      message: raw,
      messageId: 'thread-copy-msg',
    }),
  });

  context.renderChatPanel();

  const html = document.getElementById('panel-chat')._chatShell._chatParts.messages.innerHTML;
  assert.match(html, /oncontextmenu="return chatMessageContextMenu\(event, &quot;thread-copy&quot;, &quot;thread-copy-msg&quot;\)"/);
  assert.match(html, /<strong>raw bold<\/strong>/);
  assert.doesNotMatch(html, />\*\*raw bold\*\*</);

  const evt = terminalClickEvent();
  evt.clientX = 280;
  evt.clientY = 180;
  context.__ctxEvt = evt;
  assert.equal(runInContext(context, `chatMessageContextMenu(__ctxEvt, 'thread-copy', 'thread-copy-msg');`), false);

  assert.equal(evt.preventDefaultCalled, true);
  assert.equal(evt.stopPropagationCalled, true);
  assert.equal(menu.classList.contains('open'), true);
  assert.match(menu.innerHTML, />Copy<\/button>/);

  assert.equal(runInContext(context, `chatCopyMessage('thread-copy', 'thread-copy-msg');`), false);
  assert.equal(copied, raw);
  assert.equal(menu.classList.contains('open'), false);
});

