test('grid-level New worker affordance survives delta rerenders and uses standalone worker flow', () => {
  const { sandbox, document } = createSandbox({
    _currentGroup() { return 'torque'; },
    renderTerminalWorkspace() {},
    updateEventsAttentionBadge() {},
  });
  const main = document.register('main');
  Object.defineProperty(main, 'innerHTML', {
    configurable: true,
    get() { return this._innerHTML || ''; },
    set(value) {
      this._innerHTML = value;
      this.scrollTop = 0;
    },
  });
  registerAddCellModalElements(document);
  const context = vm.createContext(sandbox);
  loadScript(context, 'static/js/constants.js');
  loadScript(context, 'static/js/ws.js');
  loadScript(context, 'static/js/render.js');
  loadScript(context, 'static/js/grid/group-tabs.js');
  loadScript(context, 'static/js/grid/agent-card.js');
  loadScript(context, 'static/js/grid/terminal-row.js');
  loadScript(context, 'static/js/grid/sections.js');
  loadScript(context, 'static/js/agent-detail.js');
  loadScript(context, 'static/js/agent-focus.js');
  loadScript(context, 'static/js/grid/main.js');
  loadModalScripts(context);
  runInContext(context, `
    send = function(message) { sendCalls.push(message); };
    _cachedAgentTemplates = [];
    selectedTerminalId = null;
    focusedItemId = 'principal:torque:user';
    getFilterByWindow = function() { return false; };
    _handleFullState({
      seq: 1,
      groups: { torque: ['eng-a'] },
      group_settings: { torque: { collapsed_default: false } },
      agents: {
        'eng-a': { id: 'eng-a', name: 'Engineer A', kind: 'engineer', group: 'torque', cell_type: 'agent', status: 'running', created_at: 1 }
      },
      children: {},
      board_lanes: [],
      board_tasks: {},
      panel_events: [],
      selected_principal_id: ''
    });
  `);

  assert.doesNotMatch(main.innerHTML, /principals-row/);
  assert.match(main.innerHTML, /data-agent-grid-toolbar[\s\S]*>\+ New<\/button>/);
  assert.doesNotMatch(main.innerHTML, /class="ghost-card ghost-card--engineer|class="ghost-card ghost-card--worker|\+ New Engineer|\+ Add Worker/);
  main.scrollTop = 37;

  runInContext(context, `
    _handleDelta({
      seq: 2,
      ops: [
        { op: 'agent_upsert', id: 'eng-a', group: 'torque', activity_detail: 'still running' },
        { op: 'group_update', name: 'torque', agents: ['eng-a'] }
      ]
    });
  `);

  assert.match(main.innerHTML, /data-agent-grid-toolbar[\s\S]*>\+ New<\/button>/);
  assert.doesNotMatch(main.innerHTML, /class="ghost-card ghost-card--engineer|class="ghost-card ghost-card--worker|\+ New Engineer|\+ Add Worker/);
  assert.equal(jsonValue(context, `focusedItemId`), 'eng-a');
  assert.equal(jsonValue(context, `String(state.selected_principal_id || '')`), '');
  assert.equal(main.scrollTop, 37);

  runInContext(context, `openAddWorkerForSection('torque');`);
  assert.deepEqual(jsonValue(context, `sendCalls`), [{ cmd: 'get_config', group: 'torque' }]);
  runInContext(context, `
    _showAddModal('worker', 'torque', {
      current_path: '/repo',
      group_cells: [],
      group_settings: {},
      resolved_agent_defaults: {},
      profiles: ['Default'],
      current_profile: ''
    });
  `);
  assert.equal(document.getElementById('modal-add').classList.contains('visible'), true);
  assert.equal(document.getElementById('modal-add-title').textContent, 'New Detached Worker');
  assert.equal(document.getElementById('add-submit-btn').textContent, 'Create Worker');
  assert.match(
    document.getElementById('modal-add-summary').textContent,
    /user-owned detached worker/,
  );
  document.getElementById('add-name-input').value = 'Standalone Worker';
  document.getElementById('add-group-select').value = 'torque';

  runInContext(context, `submitAdd();`);

  const createPayload = jsonValue(context, `sendCalls[sendCalls.length - 1]`);
  assert.deepEqual(createPayload, {
    cmd: 'add_worker',
    name: 'Standalone Worker',
    group: 'torque',
    worktree: false,
  });
  assert.equal(Object.prototype.hasOwnProperty.call(createPayload, 'owner_engineer_id'), false);

  runInContext(context, `
    _handleDelta({
      seq: 3,
      ops: [
        {
          op: 'agent_upsert',
          id: 'worker-standalone',
          name: 'Standalone Worker',
          kind: 'worker',
          group: 'torque',
          cell_type: 'agent',
          status: 'running',
          created_at: 2
        },
        { op: 'group_update', name: 'torque', agents: ['eng-a', 'worker-standalone'] }
      ]
    });
  `);

  assert.match(main.innerHTML, /loose-workers-strip[\s\S]*Standalone Worker/);
  assert.doesNotMatch(main.innerHTML, /\+ Add Worker/);
  assert.ok(
    main.innerHTML.indexOf('class="loose-workers-strip"')
      > main.innerHTML.indexOf('data-engineer-id="eng-a"'),
    'orphan workers stratum should render after orphan engineer rows',
  );
  assert.doesNotMatch(main.innerHTML, /class="ghost-card ghost-card--engineer|class="ghost-card ghost-card--worker standalone-worker-card-new|\+ New Engineer|\+ Add Worker/);
  assert.doesNotMatch(main.innerHTML, /No orphan engineers\./);
  assert.doesNotMatch(main.innerHTML, /No orphan workers\./);
});

